<div class="admin-demo-banner">Catálogo de demostración · Los controles no cambian productos reales.</div><div class="admin-page-actions"><div><span class="admin-kicker">Inventario</span><h2>Todos los productos</h2><p>Buscá, filtrá y revisá el catálogo.</p></div><a class="admin-primary-button" href="<?=e(url('admin-product-create'))?>">+ Agregar producto</a></div><section class="admin-panel"><div class="admin-filters"><label><span>Buscar</span><input class="form-control" type="search" placeholder="Nombre o código" data-admin-product-search></label><label><span>Categoría</span><select class="form-select" data-admin-category-filter><option value="">Todas</option><?php foreach($adminCategories as $category):?><option><?=e($category['name'])?></option><?php endforeach;?></select></label><label><span>Estado</span><select class="form-select"><option>Todos</option><option>Activo</option><option>Inactivo</option></select></label></div><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Producto</th><th>Código</th><th>Categoría</th><th>Precio</th><th>Stock</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><?php foreach($adminProducts as $product):?><tr data-product-row data-name="<?=e(strtolower($product['name'].' '.$product['barcode']))?>" data-category="<?=e($product['category'])?>"><td><div class="admin-product-cell"><img src="<?=e(product_image($product['image']))?>" alt="" width="52" height="52"><strong><?=e($product['name'])?></strong></div></td><td><?=e($product['barcode'])?></td><td><?=e($product['category'])?></td><td><?=e(money($product['price']))?></td><td><?=e($product['stock'])?></td><td><span class="admin-status"><?=$product['active']?'Activo':'Inactivo'?></span></td><td><div class="admin-row-actions"><a href="<?=e(url('admin-product-edit'))?>">Editar</a><button type="button" data-demo-action><?=$product['active']?'Desactivar':'Activar'?></button></div></td></tr><?php endforeach;?></tbody></table></div></section>
